CREATE OR REPLACE FUNCTION calculate_agent_breach_rate(
    p_agent_id   INTEGER,
    p_start_date DATE
) RETURNS NUMERIC AS $$
BEGIN
    RETURN(
       WITH base AS (
       SELECT
          st.ticket_id,
          st.agent_id,
          st.resolution_time_minutes,
          st.sla_target_minutes,
          CASE WHEN st.resolution_time_minutes > st.sla_target_minutes THEN 1 ELSE 0 END is_sla_breached
      FROM support_tickets AS st
      WHERE st.agent_id = p_agent_id AND st.assigned_date >= p_start_date
      )
      SELECT
          ROUND(
               COALESCE(AVG(is_sla_breached) * 100, 0.00)
            , 2
            ) AS breach_rate
      FROM base
     );
END;
$$ LANGUAGE PLPGSQL;

SELECT calculate_agent_breach_rate(102, '2024-01-15') AS breach_rate;
